"""Collect finite energy-split diagnostics; no mathematical status promotion."""
from pathlib import Path
import json,csv,hashlib,argparse
import mpmath as mp
P=Path(__file__).resolve().parent

def main(expect=None):
 mp.mp.dps=240;files=sorted(P.glob('energy_*.json'));out=[];details=[]
 if expect is not None:assert len(files)==expect,(len(files),expect)
 for p in files:
  d=json.loads(p.read_text());r=d['result'];a=r['raw'];s=r['scaled'];c=r['checks'];v=d.get('materialization')
  row=dict(case=p.stem.removeprefix('energy_'),world=r['world'],m=r['m'],q=r['q'],cutoff_mode=r['cutoff_mode'],T=r['T'],evaluation_dps=r['dps'],input_dps=d['input_dps'],original_vector_dps=(v['source_vector_dps'] if v else d['input_dps']),source_A_rebuilt=bool(v),e=a['edge_amplitude_e'],e2=a['edge_amplitude_squared'],H=a['head_H'],constant_K=a['constant_source_K'],constant_head=a['constant_head'],C_T=a['finite_C_T'],edge_e2C=a['edge_energy_e2C'],X=a['cross_X'],V=a['remainder_V'],source_lambda=a['source_energy_Kf'],energy_sum=a['split_sum'],absolute_closure=a['source_energy_identity_residual'],head_negative_rows=r['negative_head_rows'],h_endpoint=c['h_boundary_trace'],source_saved_lambda_minus_Rayleigh=c['source_lambda_minus_Rayleigh'])
  if s:row.update({k:s[k] for k in ['scale_e2_logT_over_piT','R_total','R_head','R_C','R_cross','R_volume','R_sum','R_identity_residual','R_complete_defect']})
  else:row.update({k:None for k in ['scale_e2_logT_over_piT','R_total','R_head','R_C','R_cross','R_volume','R_sum','R_identity_residual','R_complete_defect']})
  delta=c['source_lambda_minus_Rayleigh']
  row['relative_saved_source_replay']=mp.nstr(abs(mp.mpf(delta)/mp.mpf(a['source_energy_Kf'])),80) if delta is not None else None
  row['edge_scaled_saved_source_replay']=mp.nstr(mp.mpf(delta)/mp.mpf(s['scale_e2_logT_over_piT']),80) if delta is not None and s else None
  row['max_raw_precision_change']=mp.nstr(max(mp.mpf(x) for x in d['precision_comparison']['raw_absolute_differences'].values()),60)
  sc=d['precision_comparison']['scaled_absolute_differences'];row['max_scaled_precision_change']=mp.nstr(max(mp.mpf(x) for x in sc.values()),60) if sc else None
  out.append(row);details.append(dict(output=p.name,output_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),serialized_input_file=d['input_file'],serialized_input_sha256=d['input_sha256'],materialization=v))
 out.sort(key=lambda x:(x['world'],x['m'],x['q'],str(x['cutoff_mode'])))
 with (P/'ENERGY_SPLIT.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(out[0]));w.writeheader();w.writerows(out)
 def maxabs(key):return max(abs(mp.mpf(x[key])) for x in out if x.get(key) is not None)
 summary=dict(status='DIAGNOSTIC_NEVER_A_PROOF',source_equations='3fef776: (5.4)–(5.7)',cases=len(out),zeta_cases=sum(x['world']=='zeta' for x in out),DH_cases=sum(x['world']=='dh' for x in out),new_source_matrix_rebuilds=sum(x['source_A_rebuilt'] for x in out),new_eigensystems=0,new_zero_searches=0,finite_source_C_not_independent_infinite_zero_tail=True,max_absolute_energy_identity_residual=mp.nstr(maxabs('absolute_closure'),80),max_edge_scaled_energy_identity_residual=mp.nstr(maxabs('R_identity_residual'),80),max_raw_arithmetic_precision_change=mp.nstr(maxabs('max_raw_precision_change'),80),max_scaled_arithmetic_precision_change=mp.nstr(maxabs('max_scaled_precision_change'),80),max_relative_saved_source_replay=mp.nstr(maxabs('relative_saved_source_replay'),80),max_edge_scaled_saved_source_replay=mp.nstr(maxabs('edge_scaled_saved_source_replay'),80),inputs_and_outputs=details)
 (P/'ENERGY_VALIDATION.json').write_text(json.dumps(summary,indent=2)+'\n')
 lines=['# Finite constant/head/cross/volume energy decomposition','','DIAGNOSTIC_NEVER_A_PROOF. Exact finite source algebra for the saved selected physical vectors; no new source eigensystem, no zero search, no independently summed infinite zero tail. Source equations are (5.4)–(5.7) in `3fef776b3bd0ebeb9d87e665432ae3e423f2dfb1`.','', 'The constant indicator has physical modal vector chi=(sqrt(L),0,...). For e=f(L/2), set h=f−e chi. The scalar coefficient C_T is K[chi] minus its finite strict low-zero head. X_T and V_T are computed from the same full source bilinear form minus the corresponding finite head pairings. All source terms remain in K; no additional zeta pole is inserted, and the DH source has none.','', 'Every head uses the true signed zero metric. For DH the realified reflected rows carry opposite signs, so its head is not replaced by the positive capacity Gram. Each selected cutoff and q is retained, including separate m120 zeta q63/q64/q65 branches.','', '| world | m | q | mode | C_T | R_head | R_C | R_cross | R_volume | R_total |','|---|---:|---:|---|---:|---:|---:|---:|---:|---:|']
 fmt=lambda z:mp.nstr(mp.mpf(z),11) if z is not None else 'undefined e=0'
 for r in out:lines.append('| '+' | '.join(str(r[k]) if k in ['world','m','q','cutoff_mode'] else fmt(r[k]) for k in ['world','m','q','cutoff_mode','C_T','R_head','R_C','R_cross','R_volume','R_total'])+' |')
 lines+=['','Here R_j divides each corresponding physical energy term by e^2 log(T)/(pi T). In particular R_C=pi T C_T/log(T). The total is the **sum of all four columns**, not the constant contribution alone. The CSV retains all unscaled H,e,C,X,V, constant source/head values, and absolute/relative closure residuals.','', '## Verification limits and reproduction','', f"Maximum absolute energy identity residual: {summary['max_absolute_energy_identity_residual']}.",f"Maximum edge-scale identity residual: {summary['max_edge_scaled_energy_identity_residual']}.",f"Maximum scaled arithmetic precision change: {summary['max_scaled_arithmetic_precision_change']}.",'', 'These two-precision changes evaluate the same source-coordinate files twice; they do not improve or certify the saved eigenvector, matrix quadrature, zero census, or nonzero endpoint. Reported ratios are floating diagnostics. If e were zero, the unscaled identity would remain but no R ratio would be formed.','', '`energy_split.py` evaluates a saved A/E/f case. `prepare_large.py` uses the pinned source moment helper to materialize the full finite A and actual finite signed head for the saved larger vectors, without an eigensolver. Its provenance records the selected-vector, source-helper, and zero-table byte hashes, quadrature order, and source arithmetic precision. The full source arch tail is analytic, not a finite zero-tail truncation.','', 'Run `python summarize_energy.py --expect '+str(len(out))+'` after reproducing the listed energy JSON cases. `ENERGY_VALIDATION.json` identifies every input and output hash. No cofinal edge law, selected-volume sign, route-state, RH claim, or interval certificate is asserted.','']
 lines.extend([f"Maximum relative difference from the original saved selected eigenvalue: {summary['max_relative_saved_source_replay']}.",f"Maximum edge-scale difference from that saved value: {summary['max_edge_scaled_saved_source_replay']}.",''])
 (P/'RESULT.md').write_text('\n'.join(lines));print(json.dumps({k:v for k,v in summary.items() if k!='inputs_and_outputs'},indent=2))

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--expect',type=int);a=p.parse_args();main(a.expect)
